import{_ as t,o as r,c as e,a3 as o}from"./chunks/framework.Dj4Lt7vj.js";const u=JSON.parse('{"title":"接入店铺和客服账号","description":"","frontmatter":{"title":"接入店铺和客服账号"},"headers":[],"relativePath":"client/shops.md","filePath":"client/shops.md","lastUpdated":1787949005000}'),l={name:"client/shops.md"};function i(s,a,n,h,d,p){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="接入店铺和客服账号" tabindex="-1">接入店铺和客服账号 <a class="header-anchor" href="#接入店铺和客服账号" aria-label="Permalink to &quot;接入店铺和客服账号&quot;">​</a></h1><p>「店铺客服」页是接待的起点。先建店铺，再把平台客服账号加进来，最后打开 AI 接待开关。</p><h2 id="页面结构" tabindex="-1">页面结构 <a class="header-anchor" href="#页面结构" aria-label="Permalink to &quot;页面结构&quot;">​</a></h2><p>页面顶部是平台切换标签（千牛、拼多多、京东、抖音、快手、闲鱼），下方按店铺分组展示客服账号卡片。每张卡片显示账号的在线状态和 AI 接待开关。</p><p>首次使用会有引导提示，跟着走一遍即可。</p><h2 id="第一步-新建店铺" tabindex="-1">第一步：新建店铺 <a class="header-anchor" href="#第一步-新建店铺" aria-label="Permalink to &quot;第一步：新建店铺&quot;">​</a></h2><ol><li>点击「新建店铺」。</li><li>填写店铺名称，选择所属平台。</li><li>创建完成后会出现转接配置引导，建议顺手完成，也可以稍后在店铺设置里补。</li></ol><p>店铺是一组客服账号的集合：同一店铺下的账号<strong>共用 AI 方案和转人工设置</strong>。没有待绑定账号时也可以先创建空店铺，稍后再加账号。</p><h2 id="第二步-添加客服账号" tabindex="-1">第二步：添加客服账号 <a class="header-anchor" href="#第二步-添加客服账号" aria-label="Permalink to &quot;第二步：添加客服账号&quot;">​</a></h2><p>从店铺卡片右侧的「添加客服」入口添加。各平台略有不同：</p><ul><li><strong>千牛</strong>：客户端会自动检测本机已登录的千牛账号，直接勾选即可；没检测到就先在千牛里登录账号，或手动输入账号后按提示完成登录。</li><li><strong>其他平台</strong>（拼多多、京东、抖音、快手、闲鱼）：点「添加客服」后客户端会打开对应平台的登录窗口，用店铺的客服账号正常登录即可。</li></ul><p>账号登录都发生在你自己的电脑上，熠智 AI 不会把账号密码传到别处。</p><h2 id="第三步-开启-ai-接待" tabindex="-1">第三步：开启 AI 接待 <a class="header-anchor" href="#第三步-开启-ai-接待" aria-label="Permalink to &quot;第三步：开启 AI 接待&quot;">​</a></h2><p>接入完成后，检查这几件事（页面上的开通清单会逐项提示）：</p><ol><li>店铺已绑定 AI 方案 —— 在店铺设置里选择方案，见<a href="/aicare-docs/solution/editor">方案编辑器</a>。</li><li>客服账号在线 —— 卡片上显示在线状态。</li><li>打开该账号的 <strong>AI 接待开关</strong>。</li></ol><p>三项都满足后，顾客的新消息就会由 AI 接待。</p><h2 id="店铺设置" tabindex="-1">店铺设置 <a class="header-anchor" href="#店铺设置" aria-label="Permalink to &quot;店铺设置&quot;">​</a></h2><p>点击店铺卡片进入店铺设置，可以：</p><ul><li>修改店铺基本信息。</li><li>选择该店铺使用的 <strong>AI 方案</strong>。</li><li>配置<strong>转接客服</strong>：哪些情况转人工、转给谁，见<a href="/aicare-docs/solution/transfer">转人工设置</a>。</li><li>设置无人在线时的<strong>离线跟进</strong>方式。</li></ul><h2 id="管理客服账号" tabindex="-1">管理客服账号 <a class="header-anchor" href="#管理客服账号" aria-label="Permalink to &quot;管理客服账号&quot;">​</a></h2><ul><li><strong>备注</strong>：给账号加备注，方便区分谁是谁。</li><li><strong>删除客服</strong>：会把该账号和它与店铺的绑定一起归档，聊天记录保留。删除后想再接待需要重新添加。</li></ul><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>一个店铺能加几个客服账号？</strong> 取决于账号剩余的客服接入位。每接入一个平台客服账号会占用一个接入位，具体数量以「账单」页当前套餐说明为准，见<a href="/aicare-docs/start/plan">套餐与开通</a>。</p><p><strong>账号显示离线？</strong> 确认对应平台窗口还开着、账号没有在别处被登出。千牛账号需要千牛窗口保持登录。</p>',24)])])}const g=t(l,[["render",i]]);export{u as __pageData,g as default};
